import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.CfX5xiXd.js";var i=JSON.parse(`{"title":"Frequently Asked Questions","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}`),a={name:`faq.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to “Frequently Asked Questions”">​</a></h1><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to “General”">​</a></h2><details class="details custom-block"><summary>Are any extensions published right now?</summary><p>Yes. The catalog lists 17 content extensions and two tracker extensions: AniList and MyAnimeList.</p></details><details class="details custom-block"><summary>What extension types are supported?</summary><p>Content and tracker extensions. Theme extensions remain unsupported; this does not remove ordinary website or reader color themes.</p></details><details class="details custom-block"><summary>Does this repository include manga or comics?</summary><p>No. It publishes extension metadata and versioned JavaScript. External services decide what they host, and users remain responsible for accessing only services and material they are authorized to use.</p></details><details class="details custom-block"><summary>Does adding the repository install every extension?</summary><p>No. Adding a repository makes its catalog visible to manko. You still choose each extension through manko&#39;s install flow.</p></details><h2 id="installation-and-repositories" tabindex="-1">Installation and repositories <a class="header-anchor" href="#installation-and-repositories" aria-label="Permalink to “Installation and repositories”">​</a></h2><details class="details custom-block"><summary>What is a compatible custom catalog?</summary><p>For manko installation, it is an HTTPS directory containing <code>versioning.json</code>, or the full URL to that file. The website&#39;s optional catalog browser also accepts <code>catalog.json</code>. Each source must have a unique ID and be a content or tracker extension; theme entries are rejected.</p></details><details class="details custom-block"><summary>Where are custom catalogs stored?</summary><p>Only in local storage for the current browser profile. There is no website account or cross-device synchronization.</p></details><details class="details custom-block"><summary>Why will a custom catalog not load?</summary><p>Common causes are a missing <code>catalog.json</code>, invalid JSON, duplicate source IDs, an unsupported extension kind, an HTTP error, or a server that does not allow cross-origin browser access.</p></details><h2 id="support" tabindex="-1">Support <a class="header-anchor" href="#support" aria-label="Permalink to “Support”">​</a></h2><details class="details custom-block"><summary>Where should I report a security vulnerability?</summary><p>Do not open a public issue containing sensitive details. Follow the repository&#39;s <a href="https://github.com/k800k/extensions/blob/main/SECURITY.md" target="_blank" rel="noreferrer">Security Policy</a>.</p></details>`,12)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};